/**
 * Local APK build. android/ is generated by expo prebuild and then removed
 * from the working tree's responsibility: the release key stays in .signing/.
 *
 * Usage: node scripts/build-android-apk.mjs stable|development
 */
import { spawnSync } from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const MOBILE_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const variant = process.argv[2];
if (variant !== 'stable' && variant !== 'development') {
  console.error('[anychess] usage: node scripts/build-android-apk.mjs stable|development');
  process.exit(1);
}

function run(command, args, extraEnv, cwd = MOBILE_ROOT) {
  const result = spawnSync(command, args, {
    cwd,
    stdio: 'inherit',
    env: { ...process.env, ...extraEnv },
  });
  if (result.status !== 0) {
    const error = new Error(`${command} failed`);
    error.status = result.status ?? 1;
    throw error;
  }
}

const androidHome = process.env.ANDROID_HOME || path.join(os.homedir(), 'android-sdk');
const client = variant === 'stable' ? 'app' : 'dev';
const env = {
  ANDROID_HOME: androidHome,
  ANDROID_SDK_ROOT: androidHome,
  CI: '1',
  EXPO_NO_TELEMETRY: '1',
  ANYCHESS_VARIANT: variant,
  EXPO_PUBLIC_APP_CLIENT: client,
  EXPO_PUBLIC_AUTH_CONFIRM_URL: 'https://sparkly-paprenjak-65f499.netlify.app/auth/confirm',
};

if (variant === 'stable') {
  run(process.execPath, [path.join(MOBILE_ROOT, 'scripts', 'ensure-supabase-public-env.mjs')], env);
  run(process.execPath, [path.join(MOBILE_ROOT, 'scripts', 'create-stable-release-keystore.mjs')], env);
  run(process.execPath, [path.join(MOBILE_ROOT, 'scripts', 'verify-release-keystore.mjs')], env);
}

const packageJson = path.join(MOBILE_ROOT, 'package.json');
const packageBackup = fs.readFileSync(packageJson);
try {
  run('pnpm', ['exec', 'expo', 'prebuild', '--platform', 'android', '--no-install', '--clean'], env);
  const gradleEnv = {
    ...env,
    PATH: `${androidHome}/cmdline-tools/latest/bin:${androidHome}/platform-tools:${process.env.PATH ?? ''}`,
  };
  const task = variant === 'stable' ? ':app:assembleRelease' : ':app:assembleDebug';
  run(
    path.join(MOBILE_ROOT, 'android', 'gradlew'),
    [task, '-PreactNativeArchitectures=arm64-v8a', '--no-daemon'],
    gradleEnv,
    path.join(MOBILE_ROOT, 'android'),
  );
} finally {
  fs.writeFileSync(packageJson, packageBackup);
}

const built =
  variant === 'stable'
    ? path.join(MOBILE_ROOT, 'android', 'app', 'build', 'outputs', 'apk', 'release', 'app-release.apk')
    : path.join(MOBILE_ROOT, 'android', 'app', 'build', 'outputs', 'apk', 'debug', 'app-debug.apk');
const outDir = path.join(os.homedir(), '.anychess-release', 'apk');
fs.mkdirSync(outDir, { recursive: true, mode: 0o700 });
const outName = variant === 'stable' ? 'AnyChess-Stable-V0.0.7.apk' : 'AnyChess-Dev.apk';
const out = path.join(outDir, outName);
fs.copyFileSync(built, out);
console.log(`[anychess] ${variant} apk ${out}`);
